local base = BaseEffect
local ResourceModule = CS.Engine.Modules.ResourceModule
local util = require 'XLua.util'
local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders
local KTool = CS.Engine.Lib.KTool
local LuaChapterEffect = CS.LuaChapterEffect
local Material = CS.UnityEngine.Material
local GameObject = CS.UnityEngine.GameObject

---@class ScreenFullWarningEffect : BaseEffect
local ScreenFullWarningEffect = Class("ScreenFullWarningEffect", BaseEffect)

function ScreenFullWarningEffect:__init()
    self._isFinish = nil
    self._loadedRes = nil
    self._co = nil
end

function ScreenFullWarningEffect:__delete()
    self._isFinish = nil
    self._loadedRes = nil
    self._co = nil
end

function ScreenFullWarningEffect:Initialize(parameters)
    base.StartEffect(self, parameters)
end

function ScreenFullWarningEffect:StartEffect(object)
    base.StartEffect(self, object)
    self.isFinish = false
    if not isNull(self._loadedRes) then
        self.isFinish = true
        return
    end
    self.co = cs_coroutine.start(function()
        local NewChapterConstants = import("Game.Chapter.NewChapterConstants")
        local loader = ResourceModule.LoadBundleAsync(NewChapterConstants.FullWarningPath, nil, true)
        while not loader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end

        if loader.IsSuccess then

            local modelIns = loader:Instantiate()
            KTool.ChangeAllLayer(modelIns, 17, 0)

            modelIns.transform:SetParent(object.transform)
            modelIns.transform.localPosition = Vector3.New(0,0,0)
            modelIns.transform.localScale = Vector3.New(1,1,1)
            modelIns.transform.localRotation = CS.UnityEngine.Quaternion.identity
            self._loadedRes = modelIns

            KTool.SetActive(modelIns.gameObject, true)


            self.loader = loader
        else
            loader:Release()
        end


        self.isFinish = true
        self.co = nil

    end)
end

function ScreenFullWarningEffect:IsFinish()
    base.IsFinish(self)
    return self.isFinish
end

function ScreenFullWarningEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function ScreenFullWarningEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    KTool.SafeDelete(self._loadedRes)
    if not isNull(self.loader) then
        self.loader:Release()
    end
end

return ScreenFullWarningEffect